const envelope = $json ?? {};

const outer = envelope.body !== undefined ? envelope.body : envelope;
const bodyRaw = typeof outer === 'string' ? (() => { try { return JSON.parse(outer); } catch (_) { return {}; } })() : outer;
const body =
  typeof bodyRaw === 'string'
    ? (() => {
        try {
          return JSON.parse(bodyRaw);
        } catch (_) {
          return {};
        }
      })()
    : bodyRaw ?? {};

const ev = body.event ?? body.type ?? '';
if (ev !== 'messages.upsert') return [];

const data = body.data ?? {};
const key = data.key ?? {};
if (key.fromMe === true) return [];

const remoteJid = String(key.remoteJid ?? '');
if (!remoteJid || remoteJid.endsWith('@g.us')) return [];

const msg = data.message ?? {};
let contentType = 'text';
let text = String(
  msg.conversation ||
    msg.extendedTextMessage?.text ||
    msg.imageMessage?.caption ||
    msg.videoMessage?.caption ||
    msg.documentMessage?.caption ||
    msg.buttonsResponseMessage?.selectedDisplayText ||
    ''
).trim();

let mediaUrl = null;
const audio = msg.audioMessage ?? msg.pttMessage ?? null;
if (audio) {
  contentType = 'audio';
  mediaUrl =
    audio.url ??
    audio.directPath ??
    (audio.mediaKey && audio.mediaKeyUrl) ??
    null;
  if (!text) {
    text = '[mensagem de voz]';
  }
}

if (!text) return [];

const phone = remoteJid.replace('@s.whatsapp.net', '').replace(/\D/g, '');
if (!phone || phone.length < 8) return [];

const providerMessageId = key.id ?? null;
const ts = data.messageTimestamp ?? data.message?.messageTimestamp ?? null;

function instStr(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'object') {
    const x = v.instanceName ?? v.name ?? v.instanceId ?? v.id;
    if (x == null || x === '') return null;
    return String(x).trim();
  }
  return String(v).trim();
}

const candidates = [
  instStr(body.instance),
  instStr(envelope.instance),
  instStr(body.instanceName),
  instStr(data.instanceName),
  instStr(data.instanceId),
  typeof body.sender === 'object'
    ? instStr(body.sender?.instance ?? body.sender?.instanceId)
    : null,
  body.session != null ? String(body.session).trim() : null,
].filter(Boolean);

const instanceIdentifier = candidates[0] ?? null;
if (!instanceIdentifier) {
  console.log('[router] descartado: sem instance_name/instance_id derivável');
  return [];
}

const correlationId = $execution?.id ? String($execution.id) : `n8n-${Date.now()}`;

const instanceKey = instanceIdentifier;

return [{
  json: {
    provider: 'evolution',
    provider_message_id: providerMessageId,
    phone,
    text,
    content_type: contentType,
    media_url: mediaUrl,
    timestamp: ts,
    push_name: data.pushName ?? null,
    instance_key: instanceKey,
    instance_name: candidates.find((c) => c && !/^\d+$/.test(c)) ?? instanceKey,
    instance_id_hint: (/^\d+$/.test(instanceKey)) ? instanceKey : (data.instanceId ? String(data.instanceId) : null),
    instance: instanceKey,
    correlation_id: correlationId,
    raw_event: body
  }
}];

const norm = $('Filtrar e Normalizar').first().json;
const raw = $input.first().json ?? {};

function stop(route, enrichment, apiStatus, parsed, diag) {
  return [{
    json: {
      route,
      api_status: apiStatus ?? null,
      normalized: norm,
      enrichment: enrichment || {},
      core_response: parsed ?? null,
      ...(diag && typeof diag === 'object' ? { diag } : {}),
    },
  }];
}

const baseUrlRaw = String($env.API_BASE_URL || '').replace(/\/$/, '');
if (!baseUrlRaw) {
  return stop('config_error', {}, null, null, { error_hint: 'API_BASE_URL' });
}

const webhookToken = String($env.CORE_WEBHOOK_TOKEN || $env.N8N_WEBHOOK_TOKEN || '').trim();
if (!webhookToken) {
  return stop('config_error', {}, null, null, { error_hint: 'CORE_WEBHOOK_TOKEN' });
}

const hmacSecret = String($env.N8N_HMAC_SECRET || '').trim();
if (hmacSecret.length > 0) {
  return stop('config_error', {}, null, null, { error_hint: 'HMAC_requires_external_signer' });
}

function unwrapBody(x) {
  if (!x || typeof x !== 'object') return {};
  if (x.body && typeof x.body === 'object') return x.body;
  if (typeof x.body === 'string') {
    try {
      return x.body ? JSON.parse(x.body) : {};
    } catch (_) {
      return { raw: x.body };
    }
  }
  return x;
}

let parsed = unwrapBody(raw);

let statusCode =
  typeof raw.statusCode === 'number'
    ? raw.statusCode
    : typeof raw.error?.statusCode === 'number'
      ? raw.error.statusCode
      : null;

// HTTP Request v4 devolve JSON da Core no root (sem statusCode) em 2xx
if (statusCode === null && parsed && typeof parsed === 'object') {
  if (parsed.ok === true || parsed.duplicate === true) {
    statusCode = 200;
  } else if (parsed.error) {
    statusCode = 400;
  }
}

if (raw.error && (statusCode === null || statusCode >= 400)) {
  const msg = raw.error.message ? String(raw.error.message) : String(raw.error);
  return stop('error', {}, statusCode, parsed, { error_hint: 'network', error_message: msg });
}

if (statusCode === null || statusCode >= 400) {
  return stop('error', {}, statusCode, parsed, { http_error: true });
}

if (parsed && parsed.duplicate === true) {
  return stop('duplicate', {}, statusCode, parsed);
}

if (!parsed || parsed.ok !== true) {
  return stop('error', {}, statusCode, parsed);
}

return [{
  json: {
    route: 'agent',
    api_status: statusCode,
    normalized: norm,
    enrichment: {
      tenant_id: parsed.tenantId ?? null,
      customer_id: parsed.customerId ?? null,
      message_id: parsed.messageId ?? null,
      correlation_id: norm.correlation_id,
      conversation_context: parsed.conversationContext ?? null,
      agent_dispatch: parsed.agentDispatch ?? null,
    },
    core_response: parsed,
  },
}];

const route = $('Registrar Core API + Roteamento').first().json;
const raw = $input.first().json ?? {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
if (!body.should_dispatch) return [];
return [{
  json: {
    ...route,
    enrichment: {
      ...route.enrichment,
      conversation_context: body.conversationContext ?? route.enrichment.conversation_context,
    },
  },
}];
